<style>
:root{--foot-ink:#1b2023;--foot-gold:#d6a62d;--foot-paper:#fbfaf7;--foot-muted:#686762;--foot-line:#e4dfd3;--foot-serif:'Fraunces','Noto Serif',Georgia,serif;--foot-sans:'DM Sans','Segoe UI',Arial,sans-serif}.foot-page{background:var(--foot-paper);color:var(--foot-ink);font-family:var(--foot-sans);overflow:hidden}.foot-page :where(h1,h2,h3,.foot-brand__monogram,.foot-brand strong,.foot-footer__brand strong){font-family:var(--foot-serif);font-optical-sizing:auto;font-feature-settings:'kern' 1,'liga' 1,'clig' 1;text-wrap:balance}.foot-container{width:min(1180px,calc(100% - 40px));margin:0 auto}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.foot-header{position:relative;z-index:20;background:var(--foot-ink);color:#fff}.foot-header__masthead{padding:20px 0}.foot-header__masthead-inner{display:flex;align-items:center;justify-content:space-between;gap:24px}.foot-brand{display:inline-flex;align-items:center;gap:12px;color:#fff;text-decoration:none}.foot-brand img{display:block;max-height:56px;max-width:190px}.foot-brand__monogram{display:grid;place-items:center;width:46px;height:46px;border:1px solid var(--foot-gold);border-radius:50%;font:700 25px var(--foot-serif);color:var(--foot-gold)}.foot-brand strong{display:block;font:700 19px var(--foot-serif);letter-spacing:0}.foot-brand small{display:block;margin-top:2px;font-size:10px;color:#d9d6cf}.foot-header__account{display:flex;align-items:center;gap:8px;font-size:14px}.foot-header__account button,.foot-header__account a{border:0;background:transparent;color:#fff;font:600 14px var(--foot-sans);cursor:pointer;text-decoration:none}.foot-header__account button:hover,.foot-header__account a:hover{color:var(--foot-gold)}.foot-navigation-wrap{position:relative;height:0}.foot-navigation{position:absolute;top:0;left:50%;transform:translateX(-50%);display:flex;align-items:center;justify-content:center;width:min(1100px,calc(100% - 40px));min-height:64px;padding:8px 28px;background:#fff;border-radius:9px;box-shadow:0 14px 28px rgba(0,0,0,.16)}.foot-navigation a{padding:11px 18px;color:#313234;font-size:14px;font-weight:700;text-decoration:none;text-transform:uppercase;white-space:nowrap}.foot-navigation a:hover{color:var(--foot-gold)}.foot-mobile-toggle{display:none}.foot-hero{position:relative;min-height:650px;background:#222}.foot-hero__slide{position:relative;display:none;min-height:650px;isolation:isolate}.foot-hero__slide.is-active{display:block}.foot-hero__slide>img{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;z-index:-2}.foot-hero__shade{position:absolute;inset:0;background:linear-gradient(90deg,rgba(0,0,0,.64),rgba(0,0,0,.22) 56%,rgba(0,0,0,.05));z-index:-1}.foot-hero__content{display:flex;min-height:650px;max-width:1180px;flex-direction:column;justify-content:flex-end;align-items:flex-start;padding-bottom:98px;color:#fff}.foot-hero__content>p,.foot-section-heading>p,.foot-about__copy>p{margin:0 0 12px;color:var(--foot-gold);font-size:14px;font-weight:700;letter-spacing:0;text-transform:uppercase}.foot-hero__content h1{max-width:770px;margin:0;font:700 clamp(44px,6vw,76px)/1.04 var(--foot-serif);letter-spacing:0}.foot-hero__content>div{max-width:630px;margin:20px 0 28px;font-size:18px;line-height:1.65}.foot-button{display:inline-flex;align-items:center;justify-content:center;min-height:45px;padding:0 24px;border:1px solid var(--foot-gold);border-radius:3px;background:var(--foot-gold);color:#fff;font-size:13px;font-weight:700;text-decoration:none;text-transform:uppercase}.foot-button:hover{background:#b98916;border-color:#b98916}.foot-button--light{background:transparent;color:#fff}.foot-section{padding:100px 0}.foot-section--paper{background:var(--foot-paper)}.foot-section-heading{text-align:center;margin:0 auto 42px}.foot-section-heading h2{margin:0;font:700 clamp(32px,4vw,48px)/1.1 var(--foot-serif);color:var(--foot-ink)}.foot-section-heading span{display:block;width:52px;height:2px;margin:20px auto 0;background:var(--foot-gold)}.foot-rail{display:grid;grid-auto-flow:column;grid-auto-columns:minmax(280px,calc((100% - 48px)/3));gap:24px;overflow-x:auto;padding:0 2px 20px;scroll-snap-type:x mandatory;scrollbar-color:var(--foot-gold) transparent}.foot-rail__item{scroll-snap-align:start}.foot-service-card{border:1px solid var(--foot-line);background:#fff;min-height:100%;box-shadow:0 8px 22px rgba(42,35,22,.05)}.foot-service-card a,.foot-story-card a,.foot-menu-card a{display:block;height:100%;color:inherit;text-decoration:none}.foot-service-card__image{position:relative;aspect-ratio:1.28;overflow:hidden}.foot-service-card__image img{width:100%;height:100%;object-fit:cover;transition:transform .3s ease}.foot-service-card:hover img,.foot-story-card:hover img,.foot-menu-card:hover img{transform:scale(1.04)}.foot-service-card__image h3{position:absolute;right:18px;bottom:-1px;left:18px;margin:0;padding:17px 18px;background:#fff;color:var(--foot-gold);font:italic 600 25px/1.16 var(--foot-serif);text-align:center}.foot-service-card__copy{padding:22px 24px 25px;color:var(--foot-muted);font-size:15px;line-height:1.65;text-align:center}.foot-about{padding:96px 0;background-image:linear-gradient(rgba(32,18,8,.66),rgba(32,18,8,.66)),var(--foot-about-image);background-position:center;background-size:cover}.foot-about__panel{display:grid;grid-template-columns:minmax(260px,.8fr) 1fr;gap:44px;align-items:center;max-width:1080px;padding:36px;background:#fff}.foot-about__panel>img{width:100%;height:420px;object-fit:cover}.foot-about__copy{padding-right:22px}.foot-about__copy h2{margin:0 0 22px;color:var(--foot-gold);font:italic 700 clamp(32px,4vw,45px)/1.12 var(--foot-serif)}.foot-about__copy>div{color:#474844;font-size:16px;line-height:1.8}.foot-about__copy .foot-button{margin-top:25px}.foot-menu-section{position:relative;padding:104px 0;background:url('https://images.unsplash.com/photo-1547592180-85f173990554?auto=format&fit=crop&w=2200&q=90') center/cover}.foot-menu-section__backdrop{position:absolute;inset:0;background:rgba(10,10,8,.8)}.foot-menu-section__inner{position:relative}.foot-section-heading--light h2{color:#fff}.foot-section-heading--light p{color:#efc75c}.foot-rail--menu{grid-auto-columns:minmax(300px,calc((100% - 48px)/3))}.foot-menu-card{overflow:hidden;background:rgba(26,25,22,.86);color:#fff;border:1px solid rgba(255,255,255,.22)}.foot-menu-card img{width:100%;aspect-ratio:1.6;object-fit:cover;transition:transform .3s ease}.foot-menu-card>div{padding:18px}.foot-menu-card a>div{padding:21px 22px}.foot-menu-card h3{min-height:53px;margin:0 0 10px;color:#f1c652;font:italic 600 23px/1.18 var(--foot-serif)}.foot-menu-card strong{display:block;margin-bottom:9px;color:#f1c652;font-size:20px}.foot-menu-card p{margin:0;color:#eee;line-height:1.55}.foot-story-card{overflow:hidden;border:1px solid var(--foot-line);background:#fff}.foot-story-card img{display:block;width:100%;aspect-ratio:1.48;object-fit:cover;transition:transform .3s ease}.foot-story-card div{padding:18px 18px 23px;text-align:center}.foot-story-card small{display:block;margin-bottom:14px;color:#9b978f;font-size:12px}.foot-story-card h3{margin:0;font-size:17px;line-height:1.4;text-transform:uppercase}.foot-team-section{padding:96px 0 110px;background:#f1eee7}.foot-team-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:22px}.foot-team-card{overflow:hidden;background:#fff;text-align:center}.foot-team-card img{display:block;width:100%;aspect-ratio:.82;object-fit:cover;filter:saturate(.86)}.foot-team-card div{padding:18px}.foot-team-card p{margin:0 0 5px;color:var(--foot-gold);font-size:12px;font-weight:700;text-transform:uppercase}.foot-team-card h3{margin:0;font:700 22px var(--foot-serif)}.foot-empty{margin:0;color:var(--foot-muted)}.foot-empty--light{color:#fff}.foot-footer{background:var(--foot-ink);color:#efeee9}.foot-footer__top{display:grid;grid-template-columns:1fr auto 1fr;gap:44px;align-items:center;padding:46px 0}.foot-footer__newsletter form{display:flex;max-width:350px}.foot-footer__newsletter input{min-width:0;flex:1;border:0;border-radius:3px 0 0 3px;padding:13px;background:#fff;font:14px var(--foot-sans)}.foot-footer__newsletter button{border:0;border-radius:0 3px 3px 0;padding:0 17px;background:var(--foot-gold);color:#fff;font:700 12px var(--foot-sans);text-transform:uppercase}.foot-footer__eyebrow{margin:0 0 12px;color:#fff;font-size:12px;font-weight:700;text-transform:uppercase}.foot-footer__brand{text-align:center}.foot-footer__brand .foot-brand__monogram{margin:0 auto 8px}.foot-footer__brand strong{display:block;font:700 20px var(--foot-serif)}.foot-footer__brand small{color:#c6c2b7}.foot-footer__social{text-align:right}.foot-footer__social>div{display:flex;justify-content:flex-end;gap:9px}.foot-footer__social a{display:grid;place-items:center;width:34px;height:34px;border-radius:50%;background:var(--foot-gold);color:#fff;font-weight:700;text-decoration:none}.foot-footer__divider{height:1px;background:rgba(255,255,255,.24)}.foot-footer__grid{display:grid;grid-template-columns:1.35fr 1fr 1fr 1.2fr;gap:36px;padding:42px 0}.foot-footer__grid h3{margin:0 0 18px;color:#fff;font-size:15px;text-transform:uppercase}.foot-footer__grid p,.foot-footer__grid li{color:#d1cec6;font-size:14px;line-height:1.65}.foot-footer__grid p{margin:0 0 6px}.foot-footer__grid a{color:inherit;text-decoration:none}.foot-footer__grid a:hover{color:var(--foot-gold)}.foot-footer__grid ul{margin:0;padding:0;list-style:none}.foot-footer__grid li+li{margin-top:9px}.foot-footer__bottom{padding:18px 0 24px;border-top:1px solid rgba(255,255,255,.12);color:#aaa79f;font-size:12px;text-align:center}
.foot-hero__content h1{font-variation-settings:'opsz' 124;font-weight:760;line-height:1.08;letter-spacing:-.025em}.foot-section-heading h2,.foot-about__copy h2{font-variation-settings:'opsz' 88;font-weight:720;letter-spacing:-.018em}.foot-service-card__image h3,.foot-menu-card h3{font-variation-settings:'opsz' 56;font-weight:650}
@media(max-width:900px){.foot-navigation a{padding:10px 10px;font-size:12px}.foot-team-grid{grid-template-columns:repeat(2,1fr)}.foot-footer__grid{grid-template-columns:repeat(2,1fr)}.foot-hero,.foot-hero__slide,.foot-hero__content{min-height:570px}.foot-about__panel{gap:26px}}
@media(max-width:640px){.foot-container{width:min(100% - 28px,1180px)}.foot-header__masthead{padding:15px 0}.foot-brand strong{font-size:17px}.foot-brand small{max-width:165px}.foot-header__account{font-size:13px}.foot-navigation-wrap{height:auto;padding:9px 0}.foot-mobile-toggle{display:block;width:100%;border:1px solid rgba(255,255,255,.35);border-radius:3px;padding:10px;background:transparent;color:#fff;font:700 13px var(--foot-sans);text-transform:uppercase}.foot-navigation{position:static;transform:none;display:none;width:100%;min-height:0;margin-top:8px;padding:8px;border-radius:3px;box-shadow:none}.foot-navigation.is-open{display:flex;flex-direction:column;align-items:stretch}.foot-navigation a{padding:11px 12px}.foot-hero,.foot-hero__slide,.foot-hero__content{min-height:540px}.foot-hero__content{padding-bottom:56px}.foot-hero__content h1{font-size:43px}.foot-hero__content>div{font-size:16px}.foot-section,.foot-team-section{padding:68px 0}.foot-rail{grid-auto-columns:84%}.foot-about{padding:56px 0}.foot-about__panel{grid-template-columns:1fr;padding:18px}.foot-about__panel>img{height:280px}.foot-about__copy{padding:5px 8px 12px}.foot-menu-section{padding:68px 0}.foot-footer__top{grid-template-columns:1fr;padding:34px 0;text-align:center}.foot-footer__newsletter form{margin:auto}.foot-footer__social{text-align:center}.foot-footer__social>div{justify-content:center}.foot-footer__grid{grid-template-columns:1fr;gap:26px;text-align:center}.foot-team-grid{grid-template-columns:repeat(2,1fr);gap:12px}.foot-team-card h3{font-size:19px}}
</style>
